def is_valid_sudoku(grid):
    """
    Returns True if the given Sudoku grid is valid according to the rules.

    Rules for a valid Sudoku grid:
    - Each row contains the digits 1 through 9 without repetition.
    - Each column contains the digits 1 through 9 without repetition.
    - Each of the nine 3x3 subgrids contains the digits 1 through 9 without repetition.

    Parameters
    ----------
    grid : list of list of int
        A 9x9 grid representing the Sudoku board, where each row is a list of integers.
        0 represents an empty cell.

    Returns
    -------
    bool
        True if the grid is valid, False otherwise.
    """

    # Helper function to check that a list contains the numbers 1 through 9 exactly once,
    # ignoring zeros (which represent empty cells).
    def is_valid_unit(unit):
        seen = set()
        for num in unit:
            if num != 0:
                if num in seen:
                    return False
                seen.add(num)
        return True

    # Check all rows
    for row in grid:
        if not is_valid_unit(row):
            return False

    # Check all columns
    for col in range(9):
        column = [grid[row_i][col] for row_i in range(9)]
        if not is_valid_unit(column):
            return False

    # Check all 3x3 subgrids
    for box_row in range(0, 9, 3):
        for box_col in range(0, 9, 3):
            box = [
                grid[row_i][col_i]
                for row_i in range(box_row, box_row + 3)
                for col_i in range(box_col, box_col + 3)
            ]
            if not is_valid_unit(box):
                return False

    return True

