def select_coins(coins, target):
    def find_combination(coins, target, current_combination=[]):
        if target == 0:
            return current_combination
        if not coins or target < coins[0]['amount']:
            return []
        with_current_coin = find_combination(coins[1:], target - coins[0]['amount'], current_combination + [coins[0]])
        without_current_coin = find_combination(coins[1:], target, current_combination)
        return with_current_coin if with_current_coin else without_current_coin

    return find_combination(coins, target)
```

