def validate_email(email):
    try:
        local, domain = email.split('@')
    except ValueError:
        raise ValueError("Email address must contain exactly one '@' symbol.")

    if not local:
        raise ValueError("The local part of the email address cannot be empty.")
    if '.' not in domain:
        raise ValueError("The domain part of the email address must contain at least one '.' character.")

    local, *sub_domains = local.split('.')
    if not local.isalnum():
        raise ValueError("Local-part can only contain alphanumeric characters and dots.")
    for sub_domain in sub_domains:
        if not (sub_domain.isalnum() or sub_domain in ['-', '_']):
            raise ValueError("Sub-domain can only contain alphanumeric characters, hyphens, and underscores.")
    local, *sub_domains = domain.split('.')
    for sub_domain in sub_domains:
        if not (sub_domain.isalnum() or sub_domain in ['-', '_']):
            raise ValueError("Domain can only contain alphanumeric characters, hyphens, and underscores.")

    print("Email address is valid.")

